import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the entire sequence of operations
custom_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void custom_ops_kernel(const float* input, float* output, int size, float add_value, float multiply_value) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] + add_value;
        val = fminf(val, 0.0f);
        val = 0.5f * val * (1.0f + tanhf(sqrtf(2.0f / M_PI) * (val + 0.044715f * val * val * val)));
        output[idx] = val * multiply_value;
    }
}

torch::Tensor custom_ops_cuda(torch::Tensor input, float add_value, float multiply_value) {
    auto size = input.numel();
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    custom_ops_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size, add_value, multiply_value);

    return output;
}
"""

custom_ops_cpp_source = (
    "torch::Tensor custom_ops_cuda(torch::Tensor input, float add_value, float multiply_value);"
)

# Compile the inline CUDA code for the custom operations
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=custom_ops_cpp_source,
    cuda_sources=custom_ops_source,
    functions=["custom_ops_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, add_value, multiply_value):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride)
        self.add_value = add_value
        self.multiply_value = multiply_value
        self.custom_ops = custom_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.custom_ops.custom_ops_cuda(x, self.add_value, self.multiply_value)
        return x
